}

Method.Source:
private void writeKCS_KBVBuildingProjectTable(Niedax.AX.TableRecordModels.TableRecord _record)
{
    System.Exception ex;

    Niedax.AX.TableRecordModels.KCS_GoodsGroup kcs_GoodsGroup = _record;
    KCS_GoodsGroup lKCS_GoodsGroup;
    KCS_GoodsId goodsId = '';

    str message = strFmt("KCS_GoodsGroup %1 entered on %2", kcs_GoodsGroup.ToString(), this.environment);

    goodsId = kcs_GoodsGroup.KCS_GoodsId;

    changecompany(_record.DataAreaId)
    {
        try
        {
            lKCS_GoodsGroup = KCS_GoodsGroup::find(goodsId, true);

            //Make only updates on an existing record, since the records are created by determination process in d365
            if(!lKCS_GoodsGroup)
            {
                message = strFmt("Record %1 inserted on %2",  kcs_GoodsGroup.ToString(), this.environment);
                lKCS_GoodsGroup.KCS_GoodsId = kcs_GoodsGroup.KCS_GoodsId;
                lKCS_GoodsGroup.KCS_GoodsDescription = kcs_GoodsGroup.KCS_GoodsDescription;
                lKCS_GoodsGroup.insert();
                response.RecId = lKCS_GoodsGroup.RecId;
                response.Success = true;
            }
            else
            {
                message = strFmt("lKCS_GoodsGroup %1 updated on %2", lKCS_GoodsGroup.KCS_GoodsId, this.environment);

                response.RecId = lKCS_GoodsGroup.RecId;
                response.Success = true;
                lKCS_GoodsGroup.KCS_GoodsDescription = kcs_GoodsGroup.KCS_GoodsDescription;
                ttsbegin;
                lKCS_GoodsGroup.doUpdate();
                ttscommit;
            }
        }
        catch(ex)
        {
            message = message + "-" + ex.Message;
            response.RecId = 0;
        }
    }

    response.Message = message;
}

/// <summary>
/// Updates or creates corresponding record
/// </summary>
/// <param name = "_record">record instance</param>
/// <returns>Response</returns>
public Niedax.D365.API.Models.D365_APIResponse writeRecord(Niedax.AX.TableRecordModels.TableRecord _record)
{
    this.writeKCS_KBVBuildingProjectTable(_record);
    return response;
}
